{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/grocery-list.json
    Groceries as a compact list: a small square picture (or none), the name, the pack size, the price and an add button, in one or two columns. Axes: thumbs (show, hide), cols (1, 2), tone.
    Props (p): id, title, lead, dishes, empty, labels, thumbs, cols, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_dishes = ($p['dishes'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_thumbs = ($p['thumbs'] ?? 'show')}
{var $v_cols = ($p['cols'] ?? '2')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_7}
  {if og_t(og_eq(og_len($v_dishes), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'shopping-bag', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_6}
      {foreach og_l($v_dishes) as $v_d}
        {capture $c_5}
          {if og_t(og_eq($v_thumbs, 'show'))}
            {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_d, ['name']), 'ratio' => '1/1', 'className' => og_cnv(['size-12 shrink-0'])]])|noescape}
          {/if}
          {capture $c_3}
            {capture $c_1}
              {=og_text(og_get($v_d, ['name']))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_1])|noescape}
            {capture $c_2}
              {=og_text(og_tpl('{0} · {1}', [og_get($v_d, ['weight']), og_get($v_d, ['tag'])]))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
          {/capture}
          {=og_include('compose/Stack.latte', ['gap' => '0', 'class' => 'min-w-0 flex-1', 'children' => (string) $c_3])|noescape}
          {capture $c_4}
            {=og_text(og_money(og_get($v_d, ['price']), og_get($v_d, ['currency'])))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'text-sm font-bold', 'children' => (string) $c_4])|noescape}
          {=og_include('blocks/add-icon.latte', ['p' => ['label' => og_tpl(og_get($v_labels, ['addOf']), [og_get($v_d, ['name'])])]])|noescape}
        {/capture}
        {=og_include('compose/ListItem.latte', ['class' => 'flex items-center gap-4 border-b border-border py-2', 'attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_5])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/List.latte', ['tag' => 'ul', 'class' => og_s((og_t(og_eq($v_cols, '2')) ? 'grid grid-cols-1 gap-x-8 md:grid-cols-2' : 'grid grid-cols-1')), 'attrs' => og_attrs(['data-testid', 'items']), 'children' => (string) $c_6])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_7)])|noescape}
